class Solution {
    public int superEggDrop(int k,int n){
        long[] reachable=new long[k+1];
        int moves=0;
        while(reachable[k]<n){
            moves++;
            for(int eggs=k;eggs>=1;eggs--)reachable[eggs]=reachable[eggs]+reachable[eggs-1]+1;
        }
        return moves;
    }
}

code.kotlin:
class Solution {
    fun superEggDrop(k:Int,n:Int):Int{
        val reachable=LongArray(k+1);
        var moves=0;
        while(reachable[k]<n){
            moves++;
            for(eggs in k downTo 1)reachable[eggs]=reachable[eggs]+reachable[eggs-1]+1
        };
        return moves
    }
}

